import random, time
from datetime import datetime as D, timedelta
from cronexpr import next_run, _compile

for e in ["SAT-SUN * * * *", "0 0 * * SAT-SUN"]:
    try: next_run(e, D(2026,1,1)); raise SystemExit(f"accepted {e}")
    except ValueError: pass
bad = ["", "* * * *", "* * * * * *", "60 * * * *", "* 24 * * *", "* * 0 * *", "* * 32 * *",
       "* * * 0 *", "* * * 13 *", "* * * * 8", "FRI-MON * * * *", "1-2-3 * * * *",
       "*/0 * * * *", "*/ * * * *", "5/ * * * *", "* * * * MON/x", "-5 * * * *",
       "1,,2 * * * *", "1, * * * *", "MON * * * *", "* * * JAN-13 *", "* * * * FOO",
       "* * * * mon-XYZ", "5-* * * * *", "+5 * * * *", "1.5 * * * *", "@sometimes",
       "@daily extra", "10-5 * * * *", "* * * * 5-1", "0 0 * * 0-7/0", "* * * * 1-7/-1"]
for e in bad:
    try: next_run(e, D(2026,1,1)); raise SystemExit(f"accepted invalid {e!r}")
    except ValueError: pass
for x in [None, 5, b"* * * * *", ["* * * * *"]]:
    try: next_run(x, D(2026,1,1)); raise SystemExit("no TypeError")
    except TypeError: pass
for ok in ["0 0 * * 0-7", "0 0 * * 7-7", "59 23 31 12 0-6", "1-5/7 * * * *",
           "0 0 * * fri-sat", "00 00 1 1 *", "0\t0 * * *", "  0 0 * * *  "]:
    _compile(ok)
print("negative cases: OK")

rnd = random.Random(1)
def rand_field(lo, hi):
    r = rnd.random()
    if r < 0.3: return "*"
    if r < 0.5: return f"{rnd.randint(lo,hi)}"
    if r < 0.7:
        a=rnd.randint(lo,hi); b=rnd.randint(a,hi); return f"{a}-{b}"
    if r < 0.85: return f"*/{rnd.randint(1,7)}"
    return f"{rnd.randint(lo,hi)}/{rnd.randint(1,9)}"
def naive(expr, after):
    minutes, hours, doms, months, dows, dr, wr = _compile(expr)
    t = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = t.replace(year=t.year+5)
    while t <= limit:
        d = t.day in doms; w = (t.weekday()+1)%7 in dows
        day = (d or w) if (dr and wr) else (d and w)
        if t.month in months and day and t.hour in hours and t.minute in minutes:
            return t
        t += timedelta(minutes=1)
    return None
n = 0
for _ in range(120):
    expr = " ".join([rand_field(0,59), rand_field(0,23), rand_field(1,31), rand_field(1,12), rand_field(0,7)])
    after = D(2026,1,1) + timedelta(minutes=rnd.randint(0, 900000))
    try: got = next_run(expr, after)
    except ValueError: got = None
    exp = naive(expr, after)
    assert got == exp, (expr, after, got, exp)
    n += 1
print(f"oracle cross-check: {n} random cases OK")

s = time.time()
for e in ["0 0 31 4 *", "59 23 31 2 *"]:
    try: next_run(e, D(2026,1,1))
    except ValueError: pass
print(f"impossible-case timing: {time.time()-s:.3f}s")
try: print("near-max:", next_run("* * * * *", D(9999,12,31,23,58,30)))
except ValueError as e: print("near-max error:", e)
try: next_run("* * * * *", D(9999,12,31,23,59)); raise SystemExit("no error at max")
except ValueError: print("at datetime max: ValueError OK")
